def solve(matrix, k):
    import heapq
    heap = [(matrix[i][0], i, 0) for i in range(len(matrix))]
    heapq.heapify(heap)
    v = None
    for _ in range(k):
        v, i, j = heapq.heappop(heap)
        if j + 1 < len(matrix[i]):
            heapq.heappush(heap, (matrix[i][j + 1], i, j + 1))
    return v

