def solve(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    count = n
    for a, b in edges:
        ra = find(a)
        rb = find(b)
        if ra != rb:
            parent[ra] = rb
            count -= 1
    return count

