def solve(begin, end, words):
    from collections import deque
    ws = set(words)
    if end not in ws:
        return 0
    q = deque([(begin, 1)])
    seen = {begin}
    while q:
        w, d = q.popleft()
        if w == end:
            return d
        for i in range(len(w)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nw = w[:i] + c + w[i + 1:]
                if nw in ws and nw not in seen:
                    seen.add(nw)
                    q.append((nw, d + 1))
    return 0

