def solve(nums):
    s = sum(nums)
    if s % 2:
        return False
    t = s // 2
    dp = [True] + [False] * t
    for x in nums:
        for j in range(t, x - 1, -1):
            if dp[j - x]:
                dp[j] = True
    return dp[t]

